const respuesta = $input.first().json.choices[0].message.content;
const longitud = respuesta.length;

let delaySegundos;

if (longitud < 50) {
  delaySegundos = 3;
} else if (longitud < 150) {
  delaySegundos = 5;
} else if (longitud < 300) {
  delaySegundos = 10;
} else if (longitud < 500) {
  delaySegundos = 15;
} else {
  delaySegundos = 20;
}

let numeroCliente = $('Webhook').first().json.body.conversation?.meta?.sender?.identifier || 
                    $('Webhook').first().json.body.sender?.identifier || "";
numeroCliente = numeroCliente.split('@')[0];

// Pasar tambien el flag de consulta lista
const consultaLista = $input.first().json.consultaLista || false;
const contactName = $input.first().json.contactName || "Cliente";
const contactPhone = $input.first().json.contactPhone || "";
const chatwootUrl = $input.first().json.chatwootUrl || "";

return [
  {
    json: {
      content: respuesta,
      delay: delaySegundos,
      delayMs: delaySegundos * 1000,
      numero: numeroCliente,
      consultaLista: consultaLista,
      contactName: contactName,
      contactPhone: contactPhone,
      chatwootUrl: chatwootUrl
    }
  }
];

const textoTranscrito = $input.first().json.text || "";
const webhookData = $('Webhook').first().json.body;

// Marcar el mensaje con tipo audio y timestamp
webhookData.content = `[AUDIO ${new Date().toISOString()}]: ${textoTranscrito}`;
webhookData._tipoMensaje = "audio";
webhookData._transcripcion = textoTranscrito;
webhookData._timestamp = Date.now();

return [
  {
    json: {
      body: webhookData
    }
  }
];

const items = $input.all();

for (const item of items) {
  if (item.binary && item.binary.data) {
    // Cambiar el nombre del archivo con extensión válida
    item.binary.data.fileName = 'audio.ogg';
    item.binary.data.mimeType = 'audio/ogg';
  }
}

return items;

const mensaje = ($input.first().json.body.content || "").toLowerCase().trim();

let comando = "desconocido";

// Detectar diferentes formas de preguntar por consultas
if (mensaje.includes("consulta") || 
    mensaje.includes("cuantas") || 
    mensaje.includes("cuantos") ||
    mensaje.includes("lista") ||
    mensaje.includes("pendiente")) {
  comando = "listar_consultas";
}

// Detectar si quiere marcar como atendida
if (mensaje.includes("atendida") || 
    mensaje.includes("completada") ||
    mensaje.includes("hecha")) {
  comando = "marcar_atendida";
}

return [{
  json: {
    comando: comando,
    mensajeOriginal: mensaje,
    conversationId: $input.first().json.body.conversation.id
  }
}];

const respuesta = $input.first().json;
const conversaciones = respuesta.data?.payload || [];
const total = conversaciones.length;

let mensaje = "";

if (total === 0) {
  mensaje = "🙏 No tienes consultas pendientes en este momento.\n\n_Cuando un cliente complete todos sus datos, apareceran aqui._";
} else {
  mensaje = `🔔 *Consultas pendientes: ${total}*\n\n`;

  conversaciones.forEach((conv, index) => {
    const nombre = conv.meta?.sender?.name || "Sin nombre";
    const telefono = conv.meta?.sender?.phone_number || "Sin teléfono";

    // Detectar tipo de servicio del último mensaje
    const mensajes = conv.messages || [];
    const mensajesCliente = mensajes.filter(m => m.message_type === 0 && m.content);
    const todosMensajes = mensajesCliente.map(m => m.content).join(" ").toLowerCase();

    let tipoServicio = "Consulta general";
    if (todosMensajes.includes("amarre")) tipoServicio = "Amarre";
    else if (todosMensajes.includes("retorno") || todosMensajes.includes("recuperar")) tipoServicio = "Retorno";
    else if (todosMensajes.includes("dominio")) tipoServicio = "Dominio";
    else if (todosMensajes.includes("alejamiento") || todosMensajes.includes("alejar")) tipoServicio = "Alejamiento";
    else if (todosMensajes.includes("endulzamiento") || todosMensajes.includes("endulzar")) tipoServicio = "Endulzamiento";
    else if (todosMensajes.includes("limpieza")) tipoServicio = "Limpieza espiritual";
    else if (todosMensajes.includes("amuleto") || todosMensajes.includes("suerte") || todosMensajes.includes("prosperidad")) tipoServicio = "Suerte/Prosperidad";
    else if (todosMensajes.includes("ex") || todosMensajes.includes("pareja") || todosMensajes.includes("esposa") || todosMensajes.includes("esposo")) tipoServicio = "Tema de pareja";

    // Buscar el primer mensaje significativo
    let resumen = "Sin detalles";
    const mensajeSignificativo = mensajesCliente.find(m => m.content && m.content.length > 20);
    if (mensajeSignificativo) {
      resumen = mensajeSignificativo.content.substring(0, 120);
      if (mensajeSignificativo.content.length > 120) resumen += "...";
    }

    mensaje += `━━━━━━━━━━━━━━━━━━━━\n`;
    mensaje += `*${index + 1}. ${nombre}*\n`;
    mensaje += `📞 ${telefono}\n`;
    mensaje += `🔮 ${tipoServicio}\n`;
    mensaje += `💬 _${resumen}_\n\n`;
  });

  mensaje += `━━━━━━━━━━━━━━━━━━━━\n`;
  mensaje += `🙏 Que la energía te acompañe`;
}

return [{
  json: {
    mensaje: mensaje,
    total: total
  }
}];

// =====================================================
// DETERMINAR MODALIDAD SEGÚN EL ÚLTIMO MENSAJE DEL CLIENTE
// =====================================================
const dataAnterior = $input.first().json;

let clienteEnvioAudio = false;

try {
  // 1. Consultar el historial completo de mensajes en Chatwoot
  const historial = $('Historial').first().json.payload || [];

  // Ordenar mensajes por fecha ascendente
  const ordenados = [...historial].sort((a, b) => (a.created_at || 0) - (b.created_at || 0));

  // Filtrar ÚNICAMENTE mensajes entrantes del cliente (message_type === 0)
  const mensajesCliente = ordenados.filter(m => m.message_type === 0 || m.message_type === "incoming");

  if (mensajesCliente.length > 0) {
    // Obtener el ÚLTIMO mensaje enviado por el cliente
    const ultimoMensajeCliente = mensajesCliente[mensajesCliente.length - 1];

    // A) Verificar si el último mensaje contiene un archivo adjunto de audio
    if (ultimoMensajeCliente.attachments && ultimoMensajeCliente.attachments.length > 0) {
      const tieneAudio = ultimoMensajeCliente.attachments.some(att => 
        att.file_type === 'audio' || 
        (att.data_url && (att.data_url.includes('.mp3') || att.data_url.includes('.ogg') || att.data_url.includes('.webm') || att.data_url.includes('.m4a')))
      );
      if (tieneAudio) clienteEnvioAudio = true;
    }

    // B) O si el contenido del texto indica que fue un audio transcrito
    if (!clienteEnvioAudio && ultimoMensajeCliente.content) {
      const txt = String(ultimoMensajeCliente.content).toLowerCase();
      if (txt.startsWith('[audio') || txt.includes('audio transcrito:')) {
        clienteEnvioAudio = true;
      }
    }
  }
} catch (e) {}

// Fallback de respaldo: Verificar si el webhook actual traía un audio
if (!clienteEnvioAudio) {
  try {
    const webhookData = $('Webhook').first().json.body || $('Webhook').first().json;
    const attachments = webhookData.attachments || webhookData.conversation?.messages?.[0]?.attachments || [];
    if (attachments.some(a => a.file_type === 'audio')) {
      clienteEnvioAudio = true;
    }
  } catch(e) {}
}

// Extraer el texto de respuesta limpio de Luna
let textoRespuesta = "";
try {
  if (dataAnterior.choices && dataAnterior.choices[0]) {
    textoRespuesta = dataAnterior.choices[0].message.content;
  } else if (dataAnterior.textoRespuesta) {
    textoRespuesta = dataAnterior.textoRespuesta;
  }
} catch (e) {}

return [{
  json: {
    ...dataAnterior,
    enviarAudio: clienteEnvioAudio,
    clienteEnvioAudio: clienteEnvioAudio,
    textoRespuesta: textoRespuesta
  }
}];

const textoOriginal = $('Verificar si Enviar Audio').first().json.textoRespuesta || "";

// Limpieza EXHAUSTIVA del texto para voz natural
let textoLimpio = textoOriginal
  // Saltos de línea y tabulaciones
  .replace(/\n/g, ' ')       
  .replace(/\r/g, ' ')       
  .replace(/\t/g, ' ')       

  // Quitar acotaciones o risas explícitas escritas (jajaja, jeje, *sonríe*)
  .replace(/\b(ja|je|ji|jo|ju|ha|he){2,}\b/gi, '')
  .replace(/\*.*?\*/g, '')
  .replace(/\[.*?\]/g, '')
  .replace(/\(.*?\)/g, '')

  // TODOS los tipos de comillas
  .replace(/["'"'`´]/g, '')
  .replace(/[""]/g, '')
  .replace(/['']/g, '')

  // Barras y símbolos
  .replace(/\\/g, '')
  .replace(/\//g, ' ')
  .replace(/\|/g, ' ')
  .replace(/\_/g, ' ')

  // Corchetes y llaves
  .replace(/\[/g, '')
  .replace(/\]/g, '')
  .replace(/\{/g, '')
  .replace(/\}/g, '')
  .replace(/\(/g, ', ')
  .replace(/\)/g, ',')

  // Símbolos especiales
  .replace(/\*/g, '')
  .replace(/\#/g, '')
  .replace(/\&/g, ' y ')
  .replace(/\@/g, ' arroba ')
  .replace(/\%/g, ' porciento')
  .replace(/\$/g, ' pesos ')
  .replace(/\+/g, ' mas ')
  .replace(/\=/g, ' igual ')
  .replace(/\</g, '')
  .replace(/\>/g, '')
  .replace(/\~/g, '')
  .replace(/\^/g, '')
  .replace(/\`/g, '')

  // Quitar emojis
  .replace(/[\u{1F300}-\u{1F9FF}]/gu, '')
  .replace(/[\u{2600}-\u{27BF}]/gu, '')
  .replace(/[\u{1F000}-\u{1F02F}]/gu, '')
  .replace(/[\u{1FA00}-\u{1FA6F}]/gu, '')
  .replace(/[\u{2700}-\u{27BF}]/gu, '')
  .replace(/[\u{1F600}-\u{1F64F}]/gu, '')
  .replace(/[\u{1F680}-\u{1F6FF}]/gu, '')

  // Suavizar puntuación excesiva
  .replace(/\.\.\./g, '.')
  .replace(/\.{2,}/g, '.')
  .replace(/,\s*,/g, ',')
  .replace(/\s+([,.!?])/g, '$1')

  // Múltiples espacios
  .replace(/\s+/g, ' ')
  .trim();

// CORTAR TEXTO RARO AL FINAL
const oraciones = textoLimpio.match(/[^.!?]+[.!?]+/g);
if (oraciones && oraciones.length > 0) {
  textoLimpio = oraciones.join(' ').trim();
}

// Limpiar puntos extra o espacios al final para evitar suspiros o ruidos raros
textoLimpio = textoLimpio.replace(/[.\s]+$/, '').trim();

// Asegurar puntuación única y limpia al final
if (!/[.!?]$/.test(textoLimpio)) {
  textoLimpio += '.';
}

// Body optimizado para Fish Audio (Temperatura 0.35 previene alucinaciones de audio al final)
const body = {
  text: textoLimpio,
  reference_id: "be2d2e9342cd4201b690500c4e35d008",
  format: "opus",
  chunk_length: 300,
  normalize: true,
  latency: "normal",
  mp3_bitrate: 128,
  top_p: 0.8,
  temperature: 0.7 // Ajuste clave: Mantiene la voz exacta de Luna pero elimina risas y ruidos finales
};

return [{
  json: {
    body: body,
    textoLimpio: textoLimpio,
    textoOriginal: textoOriginal
  }
}];

const input = $input.first().json;
const body = input.body || {};

// OpenAI usa "messages"; Gemini usaba "contents"
const mensajes = body.messages || body.contents || [];

console.log("=== DEBUG CONTEXTO ===");
console.log("Formato detectado:", body.messages ? "OpenAI" : (body.contents ? "Gemini" : "Desconocido"));
console.log("Modelo:", body.model || "N/A");
console.log("Total mensajes:", mensajes.length);
console.log("");

if (!Array.isArray(mensajes) || mensajes.length === 0) {
  console.log("⚠️ No hay mensajes en body.messages ni body.contents");
  console.log("Keys del input:", Object.keys(input));
  console.log("Keys del body:", Object.keys(body));
} else {
  mensajes.forEach((msg, i) => {
    const role = msg.role || "sin_role";

    // OpenAI: msg.content (string)
    // Gemini: msg.parts[0].text
    let texto = "";
    if (typeof msg.content === "string") {
      texto = msg.content;
    } else if (Array.isArray(msg.parts) && msg.parts[0]) {
      texto = msg.parts[0].text || "";
    } else if (Array.isArray(msg.content)) {
      // por si content viene como array de parts
      texto = msg.content.map(p => p.text || p || "").join(" ");
    }

    console.log(`Mensaje ${i + 1} (${role}):`);
    console.log(texto);
    console.log("---");
  });
}

return [$input.first()];

const inputData = $input.first().json;
const webhookData = inputData.body || inputData;
const timestamp = Date.now();
const conversationId = webhookData.conversation?.id || 0;

// Obtener el ID del mensaje actual
let mensajeId = 0;
if (webhookData.id) {
  mensajeId = webhookData.id;
} else if (webhookData.messages && webhookData.messages[0]) {
  mensajeId = webhookData.messages[0].id;
}

// Guardar el ID en el body también
webhookData._miMensajeId = mensajeId;

return [{
  json: {
    body: webhookData,
    _timestamp: timestamp,
    _conversationId: conversationId,
    _miMensajeId: mensajeId
  }
}];

const mensajes = $input.first().json.payload || [];
const guardarData = $('Guardar Timestamp').first().json;
const miTimestamp = guardarData._timestamp;
const miMensajeId = guardarData._miMensajeId;

// Filtrar solo mensajes del cliente (message_type 0)
const mensajesCliente = mensajes.filter(m => m.message_type === 0);

// Ordenar por fecha (más reciente primero)
const mensajesOrdenados = mensajesCliente.sort((a, b) => b.created_at - a.created_at);
const ultimoMensaje = mensajesOrdenados[0];

if (!ultimoMensaje) {
  return [{
    json: {
      ...guardarData,
      soyElUltimo: false,
      razon: "no hay mensajes"
    }
  }];
}

// Soy el último si mi ID es el más reciente
const soyElUltimo = ultimoMensaje.id === miMensajeId;

// También verificar: si hay mensajes en los últimos 5 segundos (cliente sigue escribiendo)
const ahoraSeg = Math.floor(Date.now() / 1000);
const hace5Seg = ahoraSeg - 5;
const mensajesRecientes = mensajesCliente.filter(m => m.created_at > hace5Seg);
const clienteSigueEscribiendo = mensajesRecientes.length > 0 && ultimoMensaje.id !== miMensajeId;

return [{
  json: {
    ...guardarData,
    soyElUltimo: soyElUltimo && !clienteSigueEscribiendo,
    miMensajeId: miMensajeId,
    ultimoMensajeId: ultimoMensaje.id,
    mensajesRecientes: mensajesRecientes.length,
    todosMensajes: mensajes
  }
}];

const data = $input.first().json;
const todosMensajes = data.todosMensajes || [];
const miTimestamp = data._timestamp || Date.now();
const miTimestampSeg = Math.floor(miTimestamp / 1000);
const hace60Seg = miTimestampSeg - 60;

// PASO 1: Obtener el mensaje actual (audio, imagen o texto)
let mensajeActual = "";
let tipoMensajeActual = "texto";

// Intentar obtener desde Inyectar Texto (audio)
try {
  const audioData = $('Inyectar Texto').first().json;
  if (audioData && audioData.body && audioData.body.content) {
    // El content viene como "[AUDIO fecha]: transcripción"
    // Extraer solo la transcripción
    const contenido = audioData.body.content;
    if (contenido.includes('[AUDIO')) {
      const match = contenido.match(/\[AUDIO[^\]]*\]:\s*(.+)/i);
      if (match) {
        mensajeActual = match[1].trim();
        tipoMensajeActual = "audio";
      } else {
        mensajeActual = contenido;
        tipoMensajeActual = "audio";
      }
    } else {
      mensajeActual = contenido;
      tipoMensajeActual = "audio";
    }
  }
} catch (e) {}

// Intentar obtener desde Inyectar Analisis (imagen)
if (!mensajeActual) {
  try {
    const imagenData = $('Inyectar Analisis').first().json;
    if (imagenData && imagenData.body && imagenData.body.content) {
      mensajeActual = imagenData.body.content;
      tipoMensajeActual = "imagen";
    }
  } catch (e) {}
}

// Si no hay audio ni imagen, es texto normal del webhook
if (!mensajeActual) {
  try {
    const webhookData = $('Webhook').first().json.body;
    if (webhookData && webhookData.content) {
      mensajeActual = webhookData.content;
      tipoMensajeActual = "texto";
    }
  } catch (e) {}
}

// PASO 2: Buscar mensajes recientes del cliente en el historial
const mensajesRecientes = todosMensajes
  .filter(m => m.message_type === 0)
  .filter(m => m.created_at >= hace60Seg)
  .sort((a, b) => a.created_at - b.created_at);

// PASO 3: Obtener el ID del mensaje actual
let miMensajeId = null;
try {
  const guardarData = $('Guardar Timestamp').first().json;
  miMensajeId = guardarData._miMensajeId;
} catch (e) {}

// PASO 4: Construir la lista
let listaConsolidada = "";
let contadorMensajes = 0;
const lineas = [];

// Agregar mensajes del historial reciente
for (const msg of mensajesRecientes) {
  let contenidoMsg = "";

  // Detectar tipo de mensaje por sus attachments
  const tieneAudio = msg.attachments && msg.attachments.some(a => a.file_type === 'audio');
  const tieneImagen = msg.attachments && msg.attachments.some(a => a.file_type === 'image');

  // Si es EL mensaje actual, usar la transcripción/análisis
  const esActual = miMensajeId && msg.id === miMensajeId;

  if (esActual && mensajeActual) {
    // Usar el mensaje actual procesado
    if (tipoMensajeActual === "audio") {
      contenidoMsg = `Audio transcrito: "${mensajeActual}"`;
    } else if (tipoMensajeActual === "imagen") {
      contenidoMsg = mensajeActual;
    } else {
      contenidoMsg = `Texto: "${mensajeActual}"`;
    }
    contadorMensajes++;
    lineas.push(`${contadorMensajes}. ${contenidoMsg}`);
  } else if (msg.content && msg.content.trim() !== '' && msg.content !== null) {
    // Mensaje anterior con contenido
    const contenido = msg.content.trim();

    // Si tiene formato [AUDIO...]
    if (contenido.includes('[AUDIO')) {
      const match = contenido.match(/\[AUDIO[^\]]*\]:\s*(.+)/i);
      if (match) {
        contenidoMsg = `Audio transcrito: "${match[1].trim()}"`;
      } else {
        contenidoMsg = contenido;
      }
    } else if (contenido.includes('[IMAGEN')) {
      contenidoMsg = contenido;
    } else {
      contenidoMsg = `Texto: "${contenido}"`;
    }
    contadorMensajes++;
    lineas.push(`${contadorMensajes}. ${contenidoMsg}`);
  } else if (tieneAudio) {
    // Audio sin contenido (mensaje anterior sin transcripción)
    contadorMensajes++;
    lineas.push(`${contadorMensajes}. [Audio anterior del cliente]`);
  } else if (tieneImagen) {
    // Imagen sin análisis
    contadorMensajes++;
    lineas.push(`${contadorMensajes}. [Imagen anterior del cliente]`);
  }
}

// Si el mensaje actual no está en las líneas, agregarlo
if (mensajeActual && !lineas.some(l => l.includes(mensajeActual))) {
  contadorMensajes++;
  if (tipoMensajeActual === "audio") {
    lineas.push(`${contadorMensajes}. Audio transcrito: "${mensajeActual}"`);
  } else if (tipoMensajeActual === "imagen") {
    lineas.push(`${contadorMensajes}. ${mensajeActual}`);
  } else {
    lineas.push(`${contadorMensajes}. Texto: "${mensajeActual}"`);
  }
}

// PASO 5: Construir el resultado final
if (contadorMensajes === 0) {
  listaConsolidada = mensajeActual || "El cliente envio un mensaje sin contenido detectable";
} else if (contadorMensajes === 1) {
  // Un solo mensaje: usarlo directamente sin formato de lista
  listaConsolidada = mensajeActual || lineas[0].replace(/^\d+\.\s*/, '');
  // Limpiar prefijos
  listaConsolidada = listaConsolidada
    .replace(/^Audio transcrito:\s*"/, '')
    .replace(/^Texto:\s*"/, '')
    .replace(/"$/, '');
} else {
  // Múltiples mensajes: crear lista
  listaConsolidada = `El cliente envio ${contadorMensajes} mensajes en los ultimos segundos:\n\n`;
  listaConsolidada += lineas.join('\n');
  listaConsolidada += "\n\nResponde de manera coherente a TODO lo que envio, en UN solo mensaje. Consolida tu respuesta y avanza el flujo.";
}

// PASO 6: Preparar el body con la lista consolidada
const webhookData = data.body;
webhookData.content = listaConsolidada;

return [{
  json: {
    body: webhookData,
    listaConsolidada: listaConsolidada,
    totalMensajes: contadorMensajes,
    mensajeActual: mensajeActual,
    tipoMensajeActual: tipoMensajeActual,
    _debug: {
      tipoDetectado: tipoMensajeActual,
      textoActual: mensajeActual,
      totalRecientes: mensajesRecientes.length,
      contadorLineas: contadorMensajes,
      lineas: lineas
    }
  }
}];

const data = $input.first().json;
const conversationId = data.body?.conversation?.id || 
                       $('Webhook').first().json.body.conversation.id;

// Verificar 1: Etiquetas de la conversación
let botPausadoManual = false;
try {
  const respConv = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://crmesteban.duckdns.org/api/v1/accounts/1/conversations/${conversationId}`,
    headers: {
      'api_access_token': 'KKaF2gF4bJZvnSkqKnR42zD8'
    },
    json: true
  });

  const labels = respConv.labels || [];
  botPausadoManual = labels.includes('bot-pausado');
} catch (e) {
  console.log('Error obteniendo conversacion:', e.message);
}

// Si está pausado manualmente, no responder
if (botPausadoManual) {
  return [{
    json: {
      ...data,
      intervencionHumana: true,
      debeResponder: false,
      motivo: "bot pausado manualmente"
    }
  }];
}

// Verificar 2: Intervención humana en últimas 24h
let mensajes = [];
try {
  const respuesta = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://crmesteban.duckdns.org/api/v1/accounts/1/conversations/${conversationId}/messages?per_page=50`,
    headers: {
      'api_access_token': 'KKaF2gF4bJZvnSkqKnR42zD8'
    },
    json: true
  });
  mensajes = respuesta.payload || [];
} catch (e) {
