const chatwootConversationId = conv.id;

if (botPuedeContestar && chatwootConversationId) {
  try {
    const convRes = await this.helpers.httpRequest({
      method: "GET",
      url: `${SUPABASE_URL}/rest/v1/conversaciones?chatwoot_conversation_id=eq.${chatwootConversationId}&select=id,agente_activo,cliente_id`,
      headers,
      json: true,
    });

    if (Array.isArray(convRes) && convRes.length > 0) {
      conversacionId = convRes[0].id;
      if (convRes[0].agente_activo === false) {
        agenteActivo = false;
      }
      clienteId = convRes[0].cliente_id;
    }

    let cliente = null;
    if (clienteId) {
      const cliRes = await this.helpers.httpRequest({
        method: "GET",
        url: `${SUPABASE_URL}/rest/v1/clientes?id=eq.${clienteId}&select=id,es_spam`,
        headers,
        json: true,
      });
      if (Array.isArray(cliRes) && cliRes.length > 0) cliente = cliRes[0];
    }

    if (cliente && cliente.es_spam === true) {
      esSpam = true;
    }
  } catch (e) {}

  if (esSpam) {
    botPuedeContestar = false;
    motivo = "spam";
  } else if (!agenteActivo) {
    botPuedeContestar = false;
    motivo = "agente_pausado";
  }
}

return [{
  json: {
    ...rawInput,
    botPuedeContestar,
    motivo,
    lunaGlobalActiva,
    crmEsSpam: esSpam,
    crmAgenteActivo: agenteActivo,
    crmTelefono: telefono,
    inboxId,
    inboxName,
    debugInfo: {
      inboxId,
      inboxName,
      senderPhone: telefono,
      botPuedeContestar,
      lunaGlobalActiva,
      motivo
    }
  }
}];

// =====================================================
// PREPARAR BINARIO OGG/OPUS Y PROPAGAR CONVERSATION ID
// =====================================================
const items = $input.all();

for (const item of items) {
  // Buscar la clave binaria (habitualmente 'data')
  const binaryKey = Object.keys(item.binary ?? {})[0];

  if (!binaryKey) {
    throw new Error(
      "No se encontró el archivo de audio. Revisa que el nodo de Fish Audio tenga activado Response Format: File."
    );
  }

  // Rescatar el archivo de audio
  const audio = item.binary[binaryKey];

  // Configurar las propiedades exactas que exige Meta y Chatwoot
  audio.fileName = `respuesta-${Date.now()}.ogg`;
  audio.fileExtension = "ogg";
  audio.mimeType = "audio/ogg; codecs=opus";

  // Asegurar que el conversationId no se pierda
  let conversationId = item.json?.conversationId;
  if (!conversationId) {
    try { conversationId = $('Detectar Cierre').first().json.conversationId; } catch(e){}
  }
  if (!conversationId) {
    try { conversationId = $('Webhook').first().json.body.conversation.id; } catch(e){}
  }

  // Dejar el binario en $binary.data y mantener el conversationId en el JSON
  item.json = {
    ...item.json,
    conversationId: String(conversationId)
  };

  item.binary = {
    data: audio
  };
}

return items;
